  "sparql": "PREFIX dexpi: <https://example.org/dexpi/> PREFIX ecad: <https://example.org/ecad/> PREFIX engineeringbom: <https://example.org/engineeringbom/> PREFIX assetinventory: <https://example.org/assetinventory/> PREFIX opcuaconnectivity: <https://example.org/opcuaconnectivity/> PREFIX productcatalog: <https://example.org/productcatalog/> SELECT ?dexpiAssetIdentifier ?ecadAssetIdentifier ?engineeringbomBOMItemId ?assetinventoryAssetIdentifier ?opcuaconnectivityAssetIdentifier ?productcatalogProductIdentifier ?engineeringbomSourceDomain ?engineeringbomSourceGroup ?assetinventoryInventoryTag ?assetinventoryOperationalSignal ?productcatalogManufacturer ?productcatalogPartNumber WHERE { ?dexpiAsset dexpi:hasAssetIdentifier ?dexpiAssetIdentifier . ?ecadAsset ecad:hasAssetIdentifier ?ecadAssetIdentifier . ?engineeringbomBOMItem engineeringbom:hasBOMItemId ?engineeringbomBOMItemId . ?assetinventoryAsset assetinventory:hasAssetIdentifier ?assetinventoryAssetIdentifier . ?opcuaconnectivityAsset opcuaconnectivity:hasAssetIdentifier ?opcuaconnectivityAssetIdentifier . ?productcatalogProduct productcatalog:hasProductIdentifier ?productcatalogProductIdentifier . ?engineeringbomBOMItem engineeringbom:hasSourceDomain ?engineeringbomSourceDomain . ?engineeringbomBOMItem engineeringbom:hasSourceGroup ?engineeringbomSourceGroup . ?assetinventoryAsset assetinventory:hasInventoryTag ?assetinventoryInventoryTag . ?assetinventoryAsset assetinventory:hasOperationalReference ?assetinventoryOperationalSignal . ?productcatalogProduct productcatalog:hasManufacturerName ?productcatalogManufacturer . ?productcatalogProduct productcatalog:hasManufacturerPartNumber ?productcatalogPartNumber . FILTER (regex(str(?dexpiAssetIdentifier), 'temperature')) }",
